<script setup lang="ts">
import { computed, ref } from 'vue'
import { ArrowLeft, ArrowRight, Check, Sparkles } from '@lucide/vue'
import TravelModal from './TravelModal.vue'
import type { TripInput, TripPreferences, TripRecord } from '../api/trips'
import { addDays, dateLabel, daysBetween, defaultPreferences, inspirationTemplates, localDate, money, paceLabels, preferences, styles } from './model'
const props=defineProps<{trip?:TripRecord|null;template?:string;busy:boolean;aiAvailable:boolean;apiError?:string}>()
const emit=defineEmits<{close:[];save:[input:TripInput,mode:'blank'|'local'|'ai']}>()
const seed=inspirationTemplates.find(item=>item.id===props.template)
const shiftStops=ref(true)
const step=ref(1),error=ref(''),name=ref(props.trip?.name||''),destination=ref(props.trip?.destination||''),start=ref(props.trip?.startsOn||addDays(localDate(),7)),end=ref(props.trip?.endsOn||addDays(start.value,(seed?.days||3)-1)),status=ref(props.trip?.status||'planning'),mode=ref<'blank'|'local'|'ai'>('blank')
const pref=ref<TripPreferences>(props.trip?preferences(props.trip):{...defaultPreferences(),...(seed?{styles:seed.styles,pace:seed.pace,checklist:seed.checklist.map(text=>({id:crypto.randomUUID(),text,done:false}))}:{})})
const days=computed(()=>daysBetween(start.value,end.value))
const title=computed(()=>name.value.trim()||`${destination.value.trim()||'我的旅行'} · ${days.value.length}天之旅`)
function validate(){if(!destination.value.trim()){error.value='先填写想去的城市或目的地';return false}if(!start.value||!end.value||start.value>end.value){error.value='请选择正确的起止日期';return false}if(addDays(start.value,59)<end.value){error.value='每趟行程最多 60 天，可以拆成多趟旅行';return false}error.value='';return true}
function next(){if(validate())step.value++}
function toggleStyle(id:string){pref.value.styles=pref.value.styles.includes(id)?pref.value.styles.filter(item=>item!==id):[...pref.value.styles,id]}
function save(){if(!validate())return;emit('save',{name:title.value,destination:destination.value.trim(),startsOn:start.value,endsOn:end.value,notes:props.trip?.notes||'',shiftStops:!!props.trip&&shiftStops.value,status:['planning','ongoing','completed'].includes(status.value)?status.value:'planning',preferences:pref.value},props.trip?'blank':mode.value)}
</script>
<template><TravelModal :title="trip?'调整这趟旅行':'从一个想去的地方开始'" eyebrow="DESIGN YOUR JOURNEY" wide :locked="busy" :error="apiError" @close="emit('close')"><form @submit.prevent="step<3?next():save()"><div class="tw-wizard-progress"><span v-for="(label,index) in ['目的地与日期','你的旅行偏好','确认并出发']" :key="label" :class="{active:step===index+1,done:step>index+1}"><i><Check v-if="step>index+1" :size="12"/><template v-else>{{ index+1 }}</template></i>{{ label }}</span></div><div class="tw-modal-body tw-wizard-body"><template v-if="step===1"><div class="tw-wizard-question"><small>01 / WHERE & WHEN</small><h3>下一站，想去哪里？</h3><p>一座城，或用顿号分隔的多个目的地。</p></div><div class="tw-field"><label for="t-destination">目的地</label><input id="t-destination" v-model="destination" maxlength="180" required placeholder="例如：杭州，或 京都、大阪"/></div><div class="tw-form-grid"><div class="tw-field"><label for="t-start">出发日期</label><input id="t-start" v-model="start" type="date" required/></div><div class="tw-field"><label for="t-end">返程日期</label><input id="t-end" v-model="end" type="date" :min="start" required/></div></div><label v-if="trip?.stops.length" class="tw-check"><input v-model="shiftStops" type="checkbox"/>改期时同步平移每天的安排，缩短天数前请先移出超出范围的日程。</label><div class="tw-field"><label for="t-name">给旅行起个名字</label><input id="t-name" v-model="name" maxlength="180" :placeholder="title"/></div><div class="tw-wizard-note">{{ days.length }} 天旅程 · 每天都可以自由添加、移动和修改安排。</div></template><template v-else-if="step===2"><div class="tw-wizard-question"><small>02 / MAKE IT YOURS</small><h3>怎样的旅行，让你期待？</h3><p>偏好用于编排行程，之后也可以随时调整。</p></div><div class="tw-field"><label>旅行节奏</label><div class="tw-choice-grid"><button v-for="(label,id) in paceLabels" :key="id" type="button" :class="{selected:pref.pace===id}" :aria-pressed="pref.pace===id" @click="pref.pace=id"><b>{{ label }}</b><small>{{ id==='relaxed'?'每天约 3 个地点':id==='balanced'?'每天约 4 个地点':'每天约 6 个地点' }}</small></button></div></div><div class="tw-field"><label>喜欢的旅行方式</label><div class="tw-style-options"><button v-for="style in styles" :key="style.id" type="button" :class="{selected:pref.styles.includes(style.id)}" :aria-pressed="pref.styles.includes(style.id)" @click="toggleStyle(style.id)"><span>{{ style.icon }}</span>{{ style.name }}<Check v-if="pref.styles.includes(style.id)" :size="12"/></button></div></div><div class="tw-form-grid"><div class="tw-field"><label for="t-travelers">同行人数</label><input id="t-travelers" v-model.number="pref.travelers" type="number" min="1" max="30" required/></div><div class="tw-field"><label for="t-transport">主要交通</label><select id="t-transport" v-model="pref.transport"><option value="transit">公共交通</option><option value="walk">步行优先</option><option value="drive">自驾出行</option></select></div></div><div class="tw-form-grid"><div class="tw-field"><label for="t-level">预算偏好</label><select id="t-level" v-model="pref.budgetLevel"><option value="economy">经济实用</option><option value="standard">舒适适中</option><option value="comfort">更重体验</option></select></div><div class="tw-field"><label for="t-budget">总预算（人民币，可留 0）</label><input id="t-budget" v-model.number="pref.budgetAmount" type="number" min="0" max="999999999" step="0.01" required/></div></div><div class="tw-field"><label for="t-departure">从哪里出发（可选）</label><input id="t-departure" v-model="pref.departure" maxlength="120" placeholder="出发城市"/></div><div class="tw-field"><label for="t-mustdo">一定想做的事</label><textarea id="t-mustdo" v-model="pref.mustDo" rows="2" maxlength="2000" placeholder="想去的地点、特别想体验的事情…"></textarea></div><div class="tw-field"><label for="t-avoid">希望避开的内容</label><textarea id="t-avoid" v-model="pref.avoid" rows="2" maxlength="2000" placeholder="用逗号分隔，收藏编排按名称与标签匹配"></textarea></div></template><template v-else><div class="tw-wizard-question"><small>03 / READY TO GO</small><h3>把期待，变成一趟旅行。</h3><p>先保存基本计划，再慢慢填上每一天。</p></div><div class="tw-trip-summary"><span class="tw-summary-icon">{{ seed?.id==='nature'?'🌿':'🧭' }}</span><h4>{{ title }}</h4><p>{{ destination }} · {{ dateLabel(start) }} — {{ dateLabel(end) }}</p><div><span>{{ days.length }} 天</span><span>{{ pref.travelers }} 人</span><span>{{ paceLabels[pref.pace] }}</span><span>{{ pref.budgetAmount?money(pref.budgetAmount):'预算待定' }}</span></div></div><div v-if="!trip" class="tw-field"><label>怎样开始？</label><div class="tw-start-options"><label><input v-model="mode" type="radio" value="blank"/><span><b>从空白行程开始</b><small>自己添加地点、交通与活动。</small></span></label><label><input v-model="mode" type="radio" value="local"/><span><b>用收藏地点智能编排</b><small>保存后生成可预览草稿，只使用你已有的目的地收藏。</small></span></label><label :class="{disabled:!aiAvailable}"><input v-model="mode" type="radio" value="ai" :disabled="!aiAvailable"/><span><b><Sparkles :size="13"/>使用外部 AI 编排</b><small>{{ aiAvailable?'将本次旅行（含备注、清单、已有安排）及相关收藏发送给已配置的 AI 服务。':'AI 服务尚未配置，仍可使用收藏编排。' }}</small></span></label></div></div><div v-else class="tw-field"><label for="t-status">行程状态</label><select id="t-status" v-model="status"><option value="planning">计划中</option><option value="ongoing">进行中</option><option value="completed">已完成</option></select></div></template><p v-if="error" role="alert" class="tw-error">{{ error }}</p></div><footer class="tw-modal-footer"><button type="button" class="tw-button secondary" :disabled="busy" @click="step>1?step--:emit('close')"><ArrowLeft v-if="step>1" :size="15"/>{{ step>1?'上一步':'取消' }}</button><span class="tw-step-caption">{{ step }} / 3</span><button type="submit" class="tw-button primary" :disabled="busy">{{ busy?'保存中…':step<3?'继续':trip?'保存旅行':'创建旅行' }}<ArrowRight v-if="!busy" :size="15"/></button></footer></form></TravelModal></template>
